```
public class IconDetector extends Detector implements ResourceFolderScanner {
    private static final Issue ICON_DENSITIES = Issue.create(
        "IconDensities",
        "Icon densities validation",
        "Icons will look best if a custom version is provided for each of the major screen density classes ...",
        Category.ICONS,
        4,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.RESOURCE_FOLDER_SCOPE)
    );

    private static final Set<String> REQUIRED_DENSITIES = new HashSet<>(Arrays.asList("mdpi", "hdpi", "xhdpi"));
    private static final Set<String> ALL_DENSITIES = new HashSet<>(Arrays.asList("ldpi", "mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi", "nodpi", "anydpi", "tvdpi"));
    private static final String INCLUDE_LDPI = "ANDROID_LINT_INCLUDE_LDPI";

    private Map<Project, Map<String, Map<String, Set<String>>>> mIcons; // project -> folderType -> baseName -> densities

    @Override
    public EnumSet<ResourceFolderType> getApplicableFolders() {
        return EnumSet.of(ResourceFolderType.DRAWABLE, ResourceFolderType.MIPMAP);
    }

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mIcons = new HashMap<>();
    }

    @Override
    public void checkFolder(@NonNull ResourceContext context, @NonNull File folder) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType != ResourceFolderType.DRAWABLE && folderType != ResourceFolderType.MIPMAP) return;
        Project project = context.getProject();
        String density = getDensity(folder);
        if (density == null) return; // no density qualifier
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isDirectory() || !isImageFile(file)) continue;
            String baseName = getBaseName(file.getName());
            Map<String, Map<String, Set<String>>> projectMap = mIcons.computeIfAbsent(project, k -> new HashMap<>());
            Map<String, Set<String>> typeMap = projectMap.computeIfAbsent(folderType.getName(), k -> new HashMap<>());
            typeMap.computeIfAbsent(baseName, k -> new HashSet<>()).add(density);
        }
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        Project project = context.getProject();
        Map<String, Map<String, Set<String>>> projectMap = mIcons.get(project);
        if (projectMap == null) return;
        boolean includeLdpi = Boolean.parseBoolean(System.getProperty(INCLUDE_LDPI, "false"))
                || Boolean.parseBoolean(System.getenv(INCLUDE_LDPI));
        Set<String> required = new HashSet<>(REQUIRED_DENSITIES);
        if (includeLdpi) required.add("ldpi");
        for (Map.Entry<String, Map<String, Set<String>>> typeEntry : projectMap.entrySet()) {
            String folderType = typeEntry.getKey();
            for (Map.Entry<String, Set<String>> iconEntry : typeEntry.getValue().entrySet()) {
                String baseName = iconEntry.getKey();
                Set<String> densities = iconEntry.getValue();
                Set<String> missing = new TreeSet<>(required);
                missing.removeAll(densities);
                if (!missing.isEmpty()) {
                    // Report on first found location
                    String message = String.format(
                        "Missing density versions for icon `%1$s` in `%2$s` folders: %3$s",
                        baseName, folderType, join(missing)
                    );
                    // Need location. We don't have file location stored. Could report at project root or first known file.
                    // For simplicity, report at project dir.
                    context.report(ICON_DENSITIES, Location.create(context.getProject().getDir()), message);
                }
            }
        }
        mIcons.remove(project);
    }
}
```

