```
private static String getBaseName(String fileName) {
    String name = fileName;
    if (name.endsWith(".9.png")) {
        return name.substring(0, name.length() - ".9.png".length());
    }
    int lastDot = name.lastIndexOf('.');
    if (lastDot != -1) {
        return name.substring(0, lastDot);
    }
    return name;
}
