@Override
public void checkBinaryResource(ResourceContext context) {
    ResourceFolderType folderType = context.getResourceFolderType();
    if (folderType != ResourceFolderType.DRAWABLE && folderType != ResourceFolderType.MIPMAP) {
        return;
    }
    File file = context.getFile();
    String name = file.getName();
    if (name.startsWith(".") || name.endsWith(".xml")) {
        return;
    }
    String folderName = file.getParentFile().getName();
    Density density = getDensity(folderName);
    if (density == null || density == Density.NODPI || density == Density.ANYDPI) {
        return;
    }
    String baseName = getBaseName(name);
    Set<Density> set = mNamesToDensities.get(baseName);
    if (set == null) {
        set = EnumSet.noneOf(Density.class);
        mNamesToDensities.put(baseName, set);
        mNamesToFiles.put(baseName, file);
    }
    set.add(density);
}
